-- 017: TSI stubs become full guides (tensioner, water pump, P2015, catch can)
update tasks set live = true, time_label = '1.5 hr', difficulty = 2 where id = 'catch-can-tsi';
update tasks set live = true, time_label = '6–8 hr', difficulty = 4 where id = 'timing-chain-tensioner';
update tasks set live = true, time_label = '45 min–3 hr', difficulty = 2 where id = 'intake-manifold-flap';
update tasks set live = true, time_label = '3–4 hr', difficulty = 3 where id = 'water-pump-tsi';
update guides set content = $j${"id": "timing-chain-tensioner", "title": "Timing chain tensioner (critical)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "tensioner-hero", "alsoFits": "All 2.0T TSI Gen 1 (CCTA/CBFA) 2008.5–2012: Mk5/Mk6 GTI, Jetta, CC, Tiguan, Eos, A3", "category": "Engine", "kind": "repair", "variants": {"question": "Tensioner only, or the full chain kit?", "hint": "The tensioner is the failure item and the reason for the job. Once the covers are off, the chains and guides are right there; on a high-mileage or tuned car most owners do the lot.", "options": [{"id": "tensioner", "label": "Tensioner only", "when": "Under ~100k, no rattle, original tensioner. Cheapest fix for the known fault."}, {"id": "full", "label": "Full chain kit", "when": "Chains, guides, tensioners, both. Adds the timing-mark work and the cam locks."}]}, "glance": {"timeFirst": "6–8 hr (tensioner) · a weekend (full kit)", "timeRepeat": "4 hr", "difficulty": 4, "cost": "$120 (tensioner) · $400–500 (kit) · $150–200 tools", "risk": "Engine timing · engine on a support bar · torque-to-yield everywhere", "why": "The original tensioner on the Gen 1 TSI can bleed down or let go, the chain goes slack, and the engine jumps time. Bent valves is the good outcome. VW's revised tensioner (06K 109 467 K) fixes it. If your 2008.5–2009 car still has the original, this is the most important job in this app, and it's within reach of a careful home mechanic with the right tools.", "note": "DAP's technician write-up is the reference; an owner thread confirms it 'is not complicated if you pay attention'. The attention part is the whole job."}, "heroCap": "Behind the passenger-side engine mount and two covers: the upper timing chain from the crank to both cams, held tight by a hydraulic tensioner on the left guide. The tensioner is two T30 bolts; getting to it is the work.", "lifespan": {"title": "When to expect it", "headline": ["Do it now if the car has the original tensioner and you can't prove otherwise"], "earliest": "Failures reported from 60,000 miles; some cars go 150k", "detail": "The warning is a rattle for a second or two on a cold start, sometimes with a P0016 cam/crank correlation code. Many failures give no warning at all, which is why owners replace it preventively. Cars built before roughly mid-2012 shipped with the old design; a 2008.5–2009 GTI certainly did unless a previous owner did this job.", "factors": ["Original tensioner", "Tune (more chain load)", "Extended oil changes", "Cold-start rattle"], "inspect": ["Cold-start rattle: stop driving it hard and plan the job. Any P0016: do not drive it."], "confidence": {"level": "high", "n": 4, "note": "Failure mode, part supersession and symptoms agree across DAP, forums and vendor listings."}}, "should": {"yesIf": ["Original tensioner (assume so unless documented)", "Rattle for 1–2 seconds on cold start", "P0016 or other cam/crank correlation codes", "Doing a clutch, water pump or other job that already has the engine supported"], "codes": ["P0016", "P0017"], "notes": ["The revised tensioner is 06K 109 467 K. It ships pinned (collapsed) and the pin comes out only after you've confirmed the chain is on its marks. The old style has a ratchet wedge; the new has a serrated shaft and a spring clip, which is how you tell them apart once the cover is off.", "Special tools are not optional: crank counter-hold (T10355) and lower gear spacer (T10368), and for the full kit the cam locks (T40271) and tensioner tools. Kits of clones cost about $190 and pay for themselves once.", "The engine mount and its bracket come off. Every bracket and mount bolt is torque-to-yield and gets replaced. Order the hardware with the tensioner: the forum parts list is in the ledger and most vendors sell it as a kit.", {"text": "Full kit adds the timing-mark discipline: coloured links on the new chains must land on the marks on the cam sprockets, crank sprocket and both balance shafts. A tooth off means bent valves. If reading that makes you hesitate, do the tensioner only, or pay a shop for this one.", "only": ["full"]}], "confidence": {"level": "high", "n": 4, "note": "Procedure from a technician write-up, cross-checked against two owner threads."}}, "parts": [{"tier": "oe", "name": "Timing chain tensioner, revised", "pn": "06K 109 467 K", "note": "Ships pinned", "price": "$100–130", "links": []}, {"tier": "oe", "name": "Full chain kit (INA): chains, guides, tensioners, gaskets", "pn": "06H 198 005 (kit)", "note": "", "price": "$350–450", "links": [], "only": ["full"]}, {"tier": "oe", "name": "Lower timing cover + 15 screws, sealant", "pn": "06H 109 210 (rev) · D 174 003 A2", "note": "Cover is usually replaced; old one distorts on removal", "price": "$60–90", "links": []}, {"tier": "oe", "name": "Crank (damper) bolt, new", "pn": "WHT 001 760 or successor", "note": "Torque-to-yield", "price": "$15", "links": []}, {"tier": "oe", "name": "Engine mount bracket bolts (×3) and mount bolts", "pn": "kit hardware", "note": "All torque-to-yield", "price": "$30", "links": []}, {"tier": "oe", "name": "Upper timing cover seals, cam adjuster magnet seal", "pn": "WHT 007 212 B (magnet seal)", "note": "In good tensioner kits", "price": "$20", "links": []}], "aftermarket": [{"name": "UroTuning / DAP tensioner service kits", "note": "Tensioner plus every seal and one-time bolt you'll disturb. Buy the kit; chasing the bolts individually costs more.", "price": "$180–250", "signal": "Buy the kit", "links": [{"store": "DAP timing chain write-up", "url": "https://www.shopdap.com/blog/post/20t-tsi-timing-chain-diy-vw-audi.html"}]}, {"name": "Clone timing tool kit (T10355, T10368, T40271, T40243/T40267, T40011)", "note": "About $190 for everything. Genuine tools are several times that.", "price": "$150–200", "signal": "Required", "links": []}], "tools": [{"name": "Engine support bar (the mount comes off) and a jack under the oil pan with a board"}, {"name": "Timing tool kit: T10355 crank counter-hold, T10368 gear spacer; T40243 + T40267 (new tensioner), T40011 (oil-pump guide pin); T40271 cam locks (full kit)", "only": ["tensioner", "full"]}, {"name": "24mm socket + long breaker bar (crank bolt), 17mm (belt tensioner pulley), 12mm triple-square (mount bracket), 10mm triple-square (guides), T30/T25, 4mm and 5mm hex"}, {"name": "Torque wrenches ¼\" (9 Nm) and ½\" (150 Nm); angle gauge; paint pen; dial or digital calipers (timing check)"}, {"name": "RTV, brake cleaner, rags; a second person for the crank bolt"}], "before": ["Read the DAP write-up end to end; this guide is the map, that has the photos.", "Engine cold, battery negative off.", "Lay every bolt out on a labelled board; the mount and cover bolts are different lengths and half are one-time-use.", "Cylinder 1 at TDC before the covers come off, and never turn the crank with the chain loose."], "steps": [{"n": 1, "title": "Access: belt, mount, upper cover", "caution": true, "blocks": [{"t": "text", "b": "Passenger side: charge-air hose and its tab off, serpentine belt off (mark direction). Engine support bar on the lift bracket, tension until the engine just lifts. Engine mount (mount-to-body and mount-to-bracket bolts) off, then the three 12mm triple-square bracket bolts and the bracket. Dipstick tube and N205 cam adjuster valve off (9 Nm bolts). Upper timing cover off."}, {"t": "warn", "b": "From here the engine hangs on the bar. Check its feet and chain before every step below."}, {"t": "ill", "id": "tensioner-hero", "cap": "What's behind the mount: upper cover over the cam sprockets, lower cover over the crank sprocket and the tensioner."}]}, {"n": 2, "title": "Set TDC, then the damper", "caution": true, "blocks": [{"t": "text", "b": "Turn the crank (24mm) to cylinder 1 TDC: cam sprocket marks line up with the cam bridge marks. Then the crank bolt: second person holding T10355 on the damper, 24mm socket through the tool, long breaker bar. Bolt out, T10368 spacer onto the crank bolt and back in hand-tight, damper off."}, {"t": "warn", "b": "The damper meshes with the lower gear on one wide key. The spacer tool keeps the gear in place and in orientation while the damper is off. Skip it and the gear can shift a tooth without you knowing. Engine damage WILL occur, in DAP's words."}]}, {"n": 3, "title": "Lower cover off", "blocks": [{"t": "text", "b": "Belt tensioner pulley off (17mm; put the bolt back loosely, the tensioner needs to move). N75 valve aside (4mm hex bolts). Turbo muffler off (3× 5mm hex). Lower timing cover: T30 bolts, then pry the cover off gently; it's sealed with RTV and usually replaced."}]}, {"n": 4, "title": "Oil-pump chain guide and the old tensioner", "blocks": [{"t": "text", "b": "Retract the oil-pump chain's tensioning guide and pin it with T40011, remove its T30 bolt, let the chain hang aside. Now look at the tensioner. Old style: a ratchet wedge on the piston. New style: serrated shaft with a spring clip. If yours is already the new style, someone did this job; you can stop here and reassemble."}, {"t": "text", "b": "Two T30 bolts hold the tensioner to the block. Remove them and the tensioner. The chain slackens but stays on its sprockets as long as the crank doesn't turn.", "only": ["tensioner"]}, {"t": "text", "b": "Retract and pin the old tensioner if you'll need it (T40011 or T40243/T40267), then its two T30 bolts. Left guide off (10mm triple-square, slide it down). Lock both cams with T40271 (an 18mm on the intake cam, or T10172 on the exhaust cam, to nudge the teeth into line). Right guide off (2× 10mm TS). Chain off. Balance-shaft tensioner (27mm) out, three lower guides (10mm TS), lower chain off, noting the balance-shaft marks point at the Torx bolts above them.", "only": ["full"]}]}, {"n": 5, "title": "New tensioner", "caution": true, "blocks": [{"t": "text", "b": "New tensioner in (still pinned), two T30 bolts.", "only": ["tensioner"]}, {"t": "torque", "label": "Timing chain tensioner bolts (T30 ×2)", "nm": 9, "c": {"level": "high", "n": 2, "note": "9 Nm (DAP technician write-up; kit sheets agree)."}, "only": ["tensioner", "full"]}, {"t": "text", "b": "Confirm the chain is still on its marks: cam sprocket marks at the bridge marks, crank at TDC. Then pull the pin. Squeeze the two long upper guides toward the centre to let the tensioner extend. Slide the small spring clip where the tensioner meets the guide as far back on the serrated shaft as it will go; it stops the piston collapsing if oil pressure is ever lost.", "only": ["tensioner"]}, {"t": "warn", "b": "Pin out only after the marks are confirmed. Once the tensioner extends, the chain is under tension in whatever position it's in.", "only": ["tensioner"]}]}, {"n": 5, "title": "New chains on the marks", "caution": true, "blocks": [{"t": "text", "b": "Lower (balance-shaft) chain: three grey links; two on the balance-shaft marks, one on the innermost crank teeth's mark. Three new guides (20 Nm). Balance-shaft tensioner in (85 Nm). Upper chain: three copper links; the two close together on the cam sprocket marks, the third on the arrow on the crank sprocket's middle teeth. Right guide on (20 Nm). Left tensioning guide: a second person holds the cam while you pull the cam lock and slide the guide up from below (20 Nm). New tensioner in (9 Nm), confirm marks, pull the pin, squeeze the guides, set the clip back.", "only": ["full"]}, {"t": "torque", "label": "Chain guides (M10 triple-square)", "nm": 20, "c": {"level": "high", "n": 2, "note": "20 Nm (DAP)."}, "only": ["full"]}, {"t": "torque", "label": "Balance-shaft chain tensioner (27mm)", "nm": 85, "c": {"level": "single", "n": 1, "note": "85 Nm (DAP); owners ask whether to pre-oil it. Follow the kit."}, "only": ["full"]}, {"t": "warn", "b": "A tooth off on any of the three sprockets means bent valves on first start. Count the links against the photos twice.", "only": ["full"]}]}, {"n": 6, "title": "Turn it over by hand, check the timing", "caution": true, "blocks": [{"t": "text", "b": "Oil-pump guide back (9 Nm). Cam bridge on if it came off (9 Nm; rotate the cams a hair with a wrench if it won't seat). Turn the crank two full turns by hand with the 24mm back to cylinder 1 TDC; it must turn freely. Measure: from the cam-cover bracket edge to the intake cam's mark, 61–64 mm; between the intake and exhaust cam marks, 124–126 mm."}, {"t": "warn", "b": "If either measurement is out, or the crank binds, stop. Do not start the engine. Recheck the marks."}]}, {"n": 7, "title": "Covers, damper, mount", "blocks": [{"t": "text", "b": "RTV bead on the new lower cover, cover on: 8-bolt covers 4 Nm + 45°, 15-bolt covers 8 Nm + 45°. Old crank bolt and spacer out, damper on with the wide key matched to the lower gear (it fits one way; check it twice), new crank bolt with the counter-hold."}, {"t": "torque", "label": "Crank (damper) bolt, NEW", "nm": 150, "alt": [100], "c": {"level": "varies", "n": 2, "note": "150 Nm + 90° (DAP article). A reader reports the superseded bolt is specified at 100 Nm + 180°. Use the figure on your bolt's box or kit sheet."}, "note": "+90° / +180°"}, {"t": "text", "b": "Turbo muffler, N75, upper cover with new seals (9 Nm), N205 and dipstick tube (9 Nm). Raise the engine on the bar, bracket on with new bolts."}, {"t": "torque", "label": "Engine mount bracket bolts (×3, NEW, 12mm TS)", "nm": 40, "c": {"level": "high", "n": 2, "note": "40 Nm + 180°, new bolts (DAP, VWVortex). Reusing the bolt and adding the angle snaps it."}, "note": "+180° turn"}, {"t": "torque", "label": "Engine mount to body / to bracket (NEW)", "nm": 40, "alt": [60], "c": {"level": "high", "n": 2, "note": "Body: 40 Nm + 90°. Bracket: 60 Nm + 90° (DAP)."}, "note": "+90° turn"}, {"t": "text", "b": "Belt tensioner pulley, belt, charge hose and tab. Battery on."}]}, {"n": 8, "title": "First start", "blocks": [{"t": "text", "b": "Crank it with the coils unplugged for a few seconds to build oil pressure, then start. A brief tick is the tensioner filling; it should be silent within seconds and stay silent on the next cold start. Check for oil at the covers after a drive."}]}], "alsoReplace": [{"name": "Full chain kit", "why": "If mileage is past 100k or the car is tuned, the chains and guides are as tired as the tensioner and they're in your hands.", "only": ["tensioner"]}, {"name": "Cam adjuster magnet seal and upper cover seals", "why": "Known oil leaks, both under the cover you removed."}, {"name": "Engine mount", "why": "It's off. A collapsed mount is common by now and shows as vibration at idle."}, {"name": "Serpentine belt and tensioner", "why": "Belt is off; if it's cracked or the tensioner is noisy, now."}, {"name": "Water pump", "why": "Not in the same space, but the same 'engine supported, coolant drained' day makes it efficient. See its guide."}], "check": {"tab": "Which tensioner?", "title": "Do I have the old one?", "illId": "tensioner-hero", "illCap": "Old: ratchet wedge on the piston. New: serrated shaft with a spring clip.", "rows": [{"see": "2008.5–2009 car, no service records", "means": "Almost certainly the original.", "do": "Replace it. Don't wait for the rattle."}, {"see": "Rattle for a second on cold start", "means": "Tensioner bleeding down overnight.", "do": "Stop driving it hard; do the job soon."}, {"see": "P0016 / P0017", "means": "Chain has moved or is about to.", "do": "Do not drive it. Tow it or do the job in place."}, {"see": "Serrated shaft and clip visible with the cover off", "means": "Already updated.", "do": "Reassemble; nothing to do."}], "c": {"level": "high", "n": 3, "note": "Vendor and forum consensus."}}, "aftercare": ["Listen on the next three cold starts.", "Check for oil at the timing covers and the cam adjuster after a week.", "Note the mileage; this is a once-per-engine job."], "disagreements": [{"topic": "Crank bolt torque", "pos": "150 Nm + 90° (article) vs 100 Nm + 180° (reader, superseded bolt).", "call": "Follow the bolt you were sold. Both shown."}, {"topic": "Tensioner only or everything?", "pos": "Vendors sell both; some techs say never open it without doing the chains.", "call": "Tensioner-only is a legitimate fix on a lower-mileage stock car; past 100k or tuned, do the kit."}, {"topic": "Home job?", "pos": "'Moderate to advanced, not every step shown' (DAP) vs 'not complicated if you pay attention' (owner).", "call": "4 out of 5. Doable; unforgiving."}], "sources": ["DAP 'How to Replace 2.0t TSI Timing Chains' (technician write-up)", "VWVortex 'DIY: TSI Timing Chain Tensioner Update'", "Humble Mechanic tensioner check article", "UroTuning / DAP tensioner kit listings"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'timing-chain-tensioner';
update guides set content = $j${"id": "water-pump-tsi", "title": "Water pump & thermostat housing", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "waterpump-hero", "alsoFits": "2.0T TSI Gen 1 (CCTA/CBFA): Mk5/Mk6 GTI, Jetta, CC, Tiguan, Eos, A3", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "3–4 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$150–250", "risk": "Coolant everywhere · awkward access behind the engine · a coupler with o-rings you can't see", "why": "The TSI's water pump lives in a plastic housing with the thermostat, bolted to the back of the block and driven by a small belt off the balance shaft. The plastic leaks, the belt strips, and an oil leak above it (cam adjuster, cover) cooks it early. Coolant smell, a low level with no puddle, or pink crust at the back of the engine are the signs.", "note": "Two owner write-ups on this exact engine; one on a 2009 GTI TSI. Neither needed the intake manifold off."}, "heroCap": "Back of the block, low, under the intake manifold: pump housing on five bolts with the belt to the balance-shaft gear, a coupler to the oil cooler, and a brace in front of it.", "lifespan": {"title": "When to expect it", "headline": ["Commonly leaking by 60,000–100,000 miles; sooner if oil has been dripping on it"], "earliest": "40k with an oil leak above it", "detail": "Weeping starts at the housing seams or the pump shaft seal. Replacement pumps that fail again almost always had an unrepaired oil leak dripping onto them, a reused belt, or a mating face that wasn't cleaned. Fix the oil leak first.", "factors": ["Oil leak from the cam adjuster or valve cover onto the pump", "Age of the plastic", "Reused belt on a previous replacement"], "inspect": ["Coolant level at every oil change; a flashlight at the back of the block below the manifold for pink crust"], "confidence": {"level": "high", "n": 3, "note": "DAP common-problems article and owner threads agree on the pattern."}}, "should": {"yesIf": ["Coolant loss with no visible puddle", "Pink or white crust behind the engine below the manifold", "Coolant smell after a drive", "Running hotter than usual or a slow-to-warm gauge (thermostat)"], "codes": ["P2181"], "notes": ["Buy the complete housing (current part 06H 121 026 ED, superseding DD, CQ, CF and others) with the thermostat, temp sensor and gasket. Pump-only kits exist but you'll be back.", "New belt (06H 121 605 E) every time. It's a small toothed belt off the balance shaft and it strips when reused.", "Coolant: G13 (or G12++ compatible), about a gallon of concentrate mixed 50/50."], "confidence": {"level": "high", "n": 3, "note": "Part strategy and belt advice consistent across two owner DIYs and the vendor."}}, "parts": [{"tier": "oe", "name": "Water pump & thermostat housing assembly", "pn": "06H 121 026 ED", "note": "Includes thermostat, sensor, gasket", "price": "$120–200", "links": []}, {"tier": "oe", "name": "Water pump belt", "pn": "06H 121 605 E", "note": "Always", "price": "$15", "links": []}, {"tier": "oe", "name": "Oil-cooler coupler o-rings / coolant pipe seals", "pn": "in most kits", "note": "", "price": "$10", "links": []}, {"tier": "oe", "name": "G13 coolant, 1 gal concentrate + distilled water", "pn": "G 013 A8J 1G", "note": "", "price": "$30", "links": []}], "aftermarket": [{"name": "Graf / Hepu aluminium-housing pump", "note": "Aluminium replaces the plastic housing. Solves the cracking; the shaft seal is still a seal. Popular upgrade.", "price": "$150–220", "signal": "Metal housing", "links": []}, {"name": "Genuine VW assembly", "note": "Latest plastic revision; fine when installed clean with a new belt.", "price": "$180–250", "signal": "OE", "links": []}], "tools": [{"name": "T25, T30, T50 Torx; 12mm socket; 8mm triple-square (splash pan)"}, {"name": "Hose-clamp pliers, long extensions with a wobble, mirror, flashlight"}, {"name": "Big drain pan(s), towels; a funnel or vacuum fill tool for bleeding"}, {"name": "Torque wrench to 10 Nm"}], "before": ["Engine cold. Coolant under pressure scalds.", "Photograph every hose and connector at the back of the engine before you touch it.", "Find and fix any oil leak above the pump area first, or the new pump dies the same way."], "steps": [{"n": 1, "title": "Drain the coolant", "blocks": [{"t": "text", "b": "Belly pan off (T25 / 8mm triple-square). Pans and towels under the radiator's lower hose; pull the hose or the drain and let it run. Reservoir cap off to help. Expect a mess; every write-up says so."}]}, {"n": 2, "title": "Make room at the back", "blocks": [{"t": "text", "b": "Engine cover off. Unplug the connectors on the throttle body side, unbolt the small bracket on the intake manifold (plastic manifold; the bolts are not tight), disconnect the hose to the coolant hard pipe at the top-back of the engine (two screws), and move the pipe. On the Mk5 the manifold itself stays put."}, {"t": "ill", "id": "waterpump-hero", "cap": "Everything is behind and below the manifold. Work from above with long extensions and from below for the bolts."}]}, {"n": 3, "title": "Hoses and brace", "blocks": [{"t": "text", "b": "Release the big coolant hoses at the pump housing (clamps). The auxiliary electric coolant pump beside it can be unbolted and moved aside with its hoses attached. Remove the brace in front of the pump: T50 into the block and a 12mm nut under the manifold."}]}, {"n": 4, "title": "Pump out", "caution": true, "blocks": [{"t": "text", "b": "Belt cover off. Five T30 bolts hold the housing to the block, plus two locating pins. Pull the housing straight away from the block first, then slide it toward the transmission to clear the coupler into the oil cooler; the lower gear and belt come out with it. Patience; it's a shimmy."}, {"t": "warn", "b": "Coolant will pour from the block and the cooler when the coupler parts. Pans ready, and keep it off the belt and the alternator."}]}, {"n": 5, "title": "Clean and fit the new housing", "caution": true, "blocks": [{"t": "text", "b": "Clean the block face to bare metal with a plastic scraper; any old gasket left here is a leak. New coupler with its o-rings into the oil cooler, wetted with coolant so it slides. New belt on the new pump's pulley and the balance-shaft gear, teeth engaged. Housing onto the pins with its new gasket, five T30 bolts snug in a criss-cross."}, {"t": "torque", "label": "Water pump housing bolts (T30 ×5)", "nm": 9, "c": {"level": "medium", "n": 2, "note": "Small bolts into aluminium; 9 Nm is the figure for the equivalent M6 fasteners on this engine (DAP). Owner DIYs say snug."}}, {"t": "warn", "b": "Don't lever the housing to seat it. If it won't sit, the coupler or belt isn't in place. Force here cracks the new plastic."}]}, {"n": 6, "title": "Reassemble", "blocks": [{"t": "text", "b": "Belt cover, brace (T50 + 12mm nut), auxiliary pump back, hoses and clamps, hard pipe, bracket, connectors. Lower radiator hose on. Belly pan later, after the leak check."}]}, {"n": 7, "title": "Fill and bleed", "caution": true, "blocks": [{"t": "text", "b": "Fill the reservoir slowly with 50/50 G13. A vacuum fill tool avoids most air; without one: cap off, heater on hot, idle with the reservoir topped until the thermostat opens and the level drops, top again, cap on. Watch the temp gauge the whole time."}, {"t": "warn", "b": "An air pocket at the thermostat reads as a cold gauge then a sudden spike. If the gauge climbs past normal, shut it off and let it settle before topping up."}]}, {"n": 8, "title": "Drive and re-check", "blocks": [{"t": "text", "b": "Drive, let it cool fully, check the level and top up. Flashlight at the back of the block for weeping after the first few heat cycles. Belly pan on once it's dry."}]}], "alsoReplace": [{"name": "The oil leak above it", "why": "Cam adjuster seal or valve cover gasket dripping onto the pump is why pumps fail early. Fix it in the same session or you'll be back."}, {"name": "Thermostat", "why": "It's in the housing you just bought; done."}, {"name": "Auxiliary coolant pump", "why": "It's in your hand. If the car has never had the after-run pump recall, check with a dealer."}, {"name": "Timing chain tensioner", "why": "Same engine-supported, coolant-drained afternoon if you're doing that too."}], "check": {"tab": "Where's the leak?", "title": "Where is the coolant going?", "illId": "waterpump-hero", "illCap": "Pink crust points at the leak.", "rows": [{"see": "Pink crust behind the engine, low", "means": "Pump housing.", "do": "This guide."}, {"see": "Crust at the top-back hard pipe", "means": "Pipe o-rings, not the pump.", "do": "Pipe seals; cheaper."}, {"see": "No trace, level dropping, white smoke", "means": "Internal (head gasket) or heater core.", "do": "Pressure test before buying a pump."}, {"see": "Oil on the pump", "means": "Cam adjuster or cover leak.", "do": "Fix the oil leak, then the pump."}], "c": {"level": "community", "n": 3, "note": "Owner threads and vendor guidance."}}, "aftercare": ["Level check after each of the first three drives.", "Re-torque nothing; re-look at the housing seams at 500 miles."], "disagreements": [{"topic": "Manifold off?", "pos": "Some Audi write-ups remove the intake manifold; the Mk5 GTI owner didn't.", "call": "Not needed on the Mk5; move the throttle-body-side hoses and bracket instead."}, {"topic": "Plastic or aluminium?", "pos": "Forum split.", "call": "Aluminium housing if it fits your budget; a clean install with a new belt matters more."}], "sources": ["GolfMKV 'Waterpump/Thermostat Replacement DIY' (2009 GTI TSI)", "Golfmk6 'DIY: TSI Water Pump Replacement' (parts)", "DAP 2.0T TSI common problems (water pump section) and part listings", "AudiWorld 2.0 TFSI water pump DIY (technique)"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'water-pump-tsi';
update guides set content = $j${"id": "intake-manifold-flap", "title": "Intake manifold flap (P2015)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "p2015-hero", "alsoFits": "2.0T TSI Gen 1 (CCTA/CBFA)", "category": "Engine", "kind": "repair", "variants": {"question": "Bracket repair or new manifold?", "hint": "The flap's actuator arm wears its plastic pivot on the manifold and the position sensor loses track, so the motor throws P2015. A bracket kit re-locates the arm without removing the manifold; the factory fix is a new manifold.", "options": [{"id": "bracket", "label": "Bracket repair kit", "when": "30–45 minutes, about $25. Most owners' choice."}, {"id": "manifold", "label": "New intake manifold", "when": "2–3 hours, $300–500. The factory fix; also clears carbon at the runners while it's off."}]}, "glance": {"timeFirst": "45 min (bracket) · 2–3 hr (manifold)", "timeRepeat": "20 min", "difficulty": 2, "cost": "$25 (bracket) · $300–500 (manifold)", "risk": "Fuel rail nearby (manifold path) · small connectors", "why": "The Gen 1 TSI manifold has tumble flaps on a shaft, moved by an electric actuator through a plastic arm. The arm's mount on the manifold wears, the flap position sensor reads out of range, and you get P2015 with a check-engine light and sometimes a rough idle. The bracket kit is a clever fix that most owners fit instead of a $400 manifold.", "note": "DAP describes the fault; the bracket kits (Dorman 911-901 and similar) come with their own sheet, which this guide follows at the level they document."}, "heroCap": "Flap actuator motor on the manifold's end, its arm to the flap shaft, and the worn pivot the bracket replaces.", "lifespan": {"title": "When to expect it", "headline": ["P2015 typically appears between 60,000 and 100,000 miles"], "earliest": "Sporadic at first, then constant", "detail": "The code often starts intermittent, clears, and returns. The motor itself is usually fine; it's the arm's pivot in the plastic manifold that wears, so replacing the motor rarely fixes it.", "factors": ["Mileage", "Heat cycles"], "inspect": ["A P2015 that comes and goes is this, not a failing motor"], "confidence": {"level": "medium", "n": 3, "note": "DAP article and owner threads; bracket-kit vendors agree on the mechanism."}}, "should": {"yesIf": ["P2015 (intake manifold runner position sensor/switch circuit range)", "Check-engine light with a slightly rough idle", "P2015 returned after someone replaced the flap motor"], "codes": ["P2015", "P2004", "P2005"], "notes": ["Don't buy a flap motor first. The code is almost always the worn arm mount on the manifold, and a bracket fixes that for $25.", {"text": "The bracket kit bolts to the actuator mount and holds the arm's pivot in its correct position, taking up the wear. Follow the kit's sheet for orientation; kits differ slightly.", "only": ["bracket"]}, {"text": "A new manifold restores everything and, with the manifold off, gives you access to the intake valves for a carbon cleaning. If the car is at 100k with a rough idle, that's an argument for this path.", "only": ["manifold"]}], "confidence": {"level": "medium", "n": 3, "note": "Consistent across vendor and owner sources; procedure detail is at kit-sheet level."}}, "parts": [{"tier": "aftermarket", "name": "P2015 repair bracket kit", "pn": "Dorman 911-901 or equivalent", "note": "Bracket, hardware, instructions", "price": "$20–30", "links": [], "only": ["bracket"]}, {"tier": "oe", "name": "Intake manifold, complete with flaps and actuator", "pn": "06J 133 201 (rev; confirm by VIN)", "note": "Includes gasket", "price": "$300–500", "links": [], "only": ["manifold"]}, {"tier": "oe", "name": "Injector seals and manifold gasket", "pn": "kit", "note": "Manifold path", "price": "$30", "links": [], "only": ["manifold"]}], "aftermarket": [{"name": "Dorman 911-901 (and clones)", "note": "The bracket that made this a 30-minute job. Steel plate, two bolts, keyed to the arm.", "price": "$20–30", "signal": "The fix", "links": []}], "tools": [{"name": "T25/T30 Torx, 8mm socket, small flat screwdriver for connectors"}, {"name": "Manifold path: 10mm / 8mm triple-square for the manifold bolts, fuel-line release tool, rags", "only": ["manifold"]}, {"name": "Scan tool to clear P2015 and check the flap adaptation"}], "before": ["Engine cool.", "Read the code and note its status (sporadic or static) so you can confirm the fix.", "Manifold path: fuel rail is right there; relieve pressure and keep sparks away."], "steps": [{"n": 1, "title": "Find the actuator", "blocks": [{"t": "text", "b": "Engine cover off. On the end of the intake manifold, the small electric actuator with a connector and a short arm to the flap shaft. Move the arm by hand: play at the pivot is the fault."}, {"t": "ill", "id": "p2015-hero", "cap": "Motor, arm, pivot. The pivot's plastic mount is what wears."}]}, {"n": 2, "title": "Fit the bracket", "only": ["bracket"], "blocks": [{"t": "text", "b": "Unplug the actuator. Remove its mounting screws, lift the actuator with its arm still attached, fit the bracket over the mount per the kit sheet so it captures the arm's pivot in the correct position, and re-fit the actuator through the bracket with the kit's hardware. Reconnect."}, {"t": "torque", "label": "Actuator / bracket screws", "nm": 3, "c": {"level": "single", "n": 1, "note": "Kit sheet: snug; plastic manifold. About 3 Nm."}}]}, {"n": 2, "title": "Manifold off", "only": ["manifold"], "caution": true, "blocks": [{"t": "text", "b": "Relieve fuel pressure (fuse or rail port). Unplug the injectors, actuator, throttle body and sensors. PCV pipe off the manifold, throttle body hoses off. Remove the manifold bolts (triple-square, top and bottom; some hide under the manifold), then pull the manifold with the injectors or leave them in the head per your preference. Rag over the intake ports immediately."}, {"t": "warn", "b": "Fuel rail is under pressure until you relieve it, and the injector ports are open holes into the cylinders. Slow down here."}]}, {"n": 3, "title": "Manifold on", "only": ["manifold"], "blocks": [{"t": "text", "b": "New gasket, new injector seals. Manifold onto the head, bolts snug in a criss-cross (about 10 Nm), then everything reconnected in reverse. This is the moment to look at the intake valves; carbon here explains a rough idle the manifold won't cure."}]}, {"n": 4, "title": "Clear and confirm", "blocks": [{"t": "text", "b": "Clear P2015 with the scan tool. Some cars want the flap adaptation run (VCDS basic settings); most just relearn. Drive it a week; the code staying gone is the confirmation."}]}], "alsoReplace": [{"name": "Intake valve carbon cleaning", "why": "Manifold off is the only time the valves are exposed. Walnut blast or careful manual cleaning.", "only": ["manifold"]}, {"name": "PCV valve", "why": "Same cover-off access on the TSI; if it's original, do it."}], "check": {"tab": "Motor or mount?", "title": "Is it the motor or the mount?", "illId": "p2015-hero", "illCap": "Play at the pivot is the tell.", "rows": [{"see": "P2015 sporadic, arm has play at the pivot", "means": "Worn mount.", "do": "Bracket kit."}, {"see": "P2015 static, motor doesn't move when commanded", "means": "Actuator or wiring.", "do": "Test the motor before buying anything; then bracket + motor if needed."}, {"see": "P2015 plus rough idle at 100k", "means": "Mount plus carbon.", "do": "Manifold path with a carbon cleaning."}], "c": {"level": "medium", "n": 3, "note": "Owner threads and DAP."}}, "aftercare": ["If the code returns with the bracket fitted, check the bracket's orientation and then the motor."], "disagreements": [{"topic": "Bracket or manifold?", "pos": "Dealers replace the manifold; owners fit the bracket.", "call": "Bracket first. Manifold only if you want the carbon access too."}], "sources": ["DAP 2.0T TSI common problems (intake flap section)", "Dorman 911-901 and equivalent kit instructions", "Owner threads on P2015 diagnosis"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'intake-manifold-flap';
update guides set content = $j${"id": "catch-can-tsi", "title": "Oil catch can install (TSI)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "catchcan-hero", "alsoFits": "2.0T TSI Gen 1 (CCTA/CBFA)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which kit?", "hint": "TSI kits all replace the factory PCV with a billet adapter and route the crankcase vent through the can to the turbo inlet. They differ in bracket location and whether the manifold port is capped or kept on a check valve.", "options": [{"id": "ie", "label": "Integrated Engineering", "when": "Billet PCV adapter, -10AN lines, bracket on the strut tower"}, {"id": "cts", "label": "CTS Turbo", "when": "Billet PCV plate, braided lines, bracket by the battery"}, {"id": "other", "label": "034 / ECS / other", "when": "Same shape; follow the kit sheet"}]}, "glance": {"timeFirst": "1.5 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$250–450", "risk": "Winter freeze · lines under the fuel rail", "why": "Same reasoning as the FSI: direct injection never washes the intake valves, so crankcase oil vapour bakes onto them. On the TSI the factory PCV is also the weak point that blows rear main seals, so a catch-can kit that replaces it does two jobs at once.", "note": "Written from the IE and CTS TSI kit documentation and owner installs; not as deeply sourced as the FSI guide, and flagged where it matters."}, "heroCap": "Crankcase vent from the PCV location on the valve cover → baffled can → turbo inlet. The manifold's vacuum port is capped or kept behind a check valve depending on the kit.", "lifespan": {"title": "When owners do this", "headline": ["With a tune, or when the PCV fails and they'd rather not buy another"], "earliest": null, "detail": "Nothing wears; owners add it for carbon and because the billet adapter deletes the failure-prone PCV diaphragm. Tuned TSIs run more crankcase pressure and benefit most.", "factors": ["Tune", "PCV failed", "Oil in the intercooler pipes"], "inspect": ["Check the can weekly at first; empty at about 2 inches"], "confidence": {"level": "community", "n": 3, "note": "Vendor positioning and owner reports."}}, "should": {"yesIf": ["Tuned car", "PCV has failed (again)", "Oil in the charge pipes", "You want to slow intake-valve carbon"], "codes": [], "notes": ["Recirculating kits only; vent-to-atmosphere is messy and illegal.", "Winter: crankcase vapour is mostly water in cold weather and it can freeze in the can and lines. Drain weekly near freezing; below freezing, many owners reconnect the factory route for the season. A frozen vent blows seals.", "Kits differ on the manifold port: some cap it (all vent goes through the can under boost and vacuum), some keep a check valve so idle vacuum still pulls through the can. Follow yours."], "confidence": {"level": "medium", "n": 3, "note": "Reasoning is solid; hardware detail is at kit-sheet level."}}, "parts": [{"tier": "aftermarket", "name": "TSI catch can kit", "pn": "see options below", "note": "Billet PCV adapter/plate, can, bracket, lines, manifold cap or check valve", "price": "$250–450", "links": []}, {"tier": "oe", "name": "Clean engine oil for o-rings, zip ties", "pn": "—", "note": "", "price": "—", "links": []}], "aftermarket": [{"name": "Integrated Engineering TSI catch can kit", "note": "Billet PCV adapter replaces the factory valve, -10AN braided lines, bracket, T-handle drain. Recirculates to the turbo inlet.", "price": "$350–450", "signal": "Best documented", "links": []}, {"name": "CTS Turbo TSI kit", "note": "Billet PCV plate, braided lines, bracket. Popular with the K04 crowd.", "price": "$250–350", "signal": "Tuner pick", "links": []}, {"name": "034Motorsport / ECS TSI kits", "note": "Same idea, different hardware and bracket placement.", "price": "$300–400", "signal": "Fine choices", "links": []}], "tools": [{"name": "T30 (PCV screws), 10mm and 13mm sockets for the bracket"}, {"name": "AN wrench or taped adjustable, connector release tool, hose-clamp pliers"}], "before": ["Engine cold. Read the kit sheet alongside this.", "Oil every o-ring before threading an AN fitting; never over-tighten.", "Route lines clear of the fuel rail, coil packs and anything hot."], "steps": [{"n": 1, "title": "Cover off, PCV off", "blocks": [{"t": "text", "b": "Engine cover off. Disconnect the PCV vent hose to the manifold at both ends (spring clasps). Remove the factory PCV's Torx screws and lift it off the head; clean the face. See the TSI PCV guide for detail."}, {"t": "ill", "id": "catchcan-hero", "cap": "Same flow as the FSI: vent → can → turbo inlet."}]}, {"n": 2, "title": "Billet adapter on", "blocks": [{"t": "text", "b": "Kit's gasket or o-ring, billet PCV adapter/plate onto the head with the factory or supplied screws, snug (about 4 Nm; small screws into aluminium). Oil the o-ring and thread the feed line's fitting into the adapter by hand, then snug."}, {"t": "torque", "label": "Adapter screws", "nm": 4, "c": {"level": "single", "n": 1, "note": "Kit sheets: snug. Small screws into aluminium."}}]}, {"n": 3, "title": "Manifold port", "blocks": [{"t": "text", "b": "Cap the manifold's PCV port with the kit's plug and clip (IE and most others), or fit the kit's check valve inline if yours keeps the vacuum path. Either way, no open port.", "only": ["ie", "cts", "other"]}]}, {"n": 4, "title": "Mount the can, connect the return", "blocks": [{"t": "text", "b": "Bracket to its point (IE: strut-tower area; CTS: by the battery; per sheet), can loose in the bracket. Return line from the can to the turbo inlet pipe's breather port (the kit supplies the fitting or a hose barb for the factory port). Feed to the can's feed side, return from the return side; they are not interchangeable."}]}, {"n": 5, "title": "Route, tighten, start", "caution": true, "blocks": [{"t": "text", "b": "Walk both lines: under nothing sharp, clear of the fuel rail and coils, no contact with the belt side. Snug the AN fittings, lock the can, cover on. Start it and listen for hiss at the adapter."}, {"t": "warn", "b": "An open or leaking vent is a lean condition and an oil mess. Ten minutes of routing."}]}], "alsoReplace": [{"name": "Rear main seal check", "why": "If the PCV that this replaced had failed, look for oil at the bellhousing."}, {"name": "Turbo inlet coupler", "why": "Hardened factory couplers are a common TSI boost leak; the kit's fitting goes into this pipe anyway."}], "check": {"tab": "Which kit?", "title": "Which kit?", "illId": "catchcan-hero", "illCap": "All three routes end at the turbo inlet.", "rows": [{"see": "Want the most documented install", "means": "IE's kit has the sheet and the videos.", "do": "IE."}, {"see": "Tuned, want the tuner's kit", "means": "CTS.", "do": "CTS."}, {"see": "Already have an 034/ECS can from another car", "means": "Adapter and lines are what you need.", "do": "Buy the TSI PCV adapter and plumb it."}], "c": {"level": "community", "n": 3, "note": "Vendor material."}}, "aftercare": ["Weekly checks at first; empty at 2 inches.", "Winter: drain weekly or reconnect the factory route."], "disagreements": [{"topic": "Cap the manifold port or check-valve it?", "pos": "Kits differ.", "call": "Follow your kit; both work when installed as designed."}], "sources": ["IE and CTS TSI catch can kit documentation and listings", "Owner installs on Mk6 TSI (same engine)", "FSI catch can guide sources (mechanism, winter warning)"], "embeds": []}$j$::jsonb, updated_at = now(), created_at = now() where id = 'catch-can-tsi';
